 21	package com.pousadamarealta.api;
 22	
 23	import com.fasterxml.jackson.databind.JsonNode;
 24	import io.javalin.Javalin;
 25	import io.javalin.http.Context;
 26	import com.pousadamarealta.model.Reservation;
 27	import com.pousadamarealta.model.Room;
 28	import com.pousadamarealta.service.*;
 29	import com.pousadamarealta.util.PricingUtil;
 30	import com.pousadamarealta.util.ValidationUtil;
 31	import java.math.BigDecimal;
 32	import java.time.LocalDate;
 33	import java.time.YearMonth;
 34	import java.util.List;
 35	
 36	public class HotelAPI {
 37	    public static void setup(Javalin app) {
 38	        app.get("/rooms", HotelAPI::listRooms);
 39	        app.post("/reservations", HotelAPI::createReservation);
 40	        app.get("/reservations/{id}", HotelAPI::getReservation);
 41	        app.post("/reservations/{id}/confirmation", HotelAPI::confirmReservation);
 42	        app.post("/reservations/{id}/check-in", HotelAPI::checkIn);
 43	        app.post("/reservations/{id}/check-out", HotelAPI::checkOut);
 44	        app.post("/reservations/{id}/cancellation", HotelAPI::cancelReservation);
 45	        app.get("/reservations/{id}/document", HotelAPI::getDocument);
 46	        app.get("/messages", HotelAPI::getMessages);
 47	        app.get("/reports/occupancy", HotelAPI::getOccupancyReport);
 48	        app.get("/reports/revenue", HotelAPI::getRevenueReport);
 49	    }
 50	
 51	    private static void listRooms(Context ctx) {
 52	        try {
 53	            List<Room> rooms = RoomService.getAllRooms();
 54	            ctx.json(rooms.stream().map(r -> new Object() {
 55	                public int number = r.number;
 56	                public String type = r.type;
 57	                public int capacity = r.capacity;
 58	                public BigDecimal nightlyRate = r.nightlyRate;
 59	            }).toList());
 60	        } catch (Exception e) {
 61	            error(ctx, 500, "INTERNAL_ERROR", e.getMessage());
 62	        }
 63	    }
 64	
 65	    private static void createReservation(Context ctx) {
 66	        try {
 67	            JsonNode body = ctx.bodyAsClass(JsonNode.class);
 68	
 69	            if (!hasRequiredFields(body, "roomNumber", "guestName", "guestEmail", "guestCpf",
 70	                                   "checkIn", "checkOut", "guests", "ratePlan")) {
 71	                error(ctx, 400, "INVALID_REQUEST", "Missing required fields");
 72	                return;
 73	            }
 74	
 75	            int roomNumber = body.get("roomNumber").asInt();
 76	            String guestName = body.get("guestName").asText();
 77	            String guestEmail = body.get("guestEmail").asText();
 78	            String guestCpf = body.get("guestCpf").asText();
 79	            int guests = body.get("guests").asInt();
 80	            String ratePlan = body.get("ratePlan").asText();
 81	
 82	            LocalDate checkIn = ValidationUtil.parseDate(body.get("checkIn").asText());
 83	            LocalDate checkOut = ValidationUtil.parseDate(body.get("checkOut").asText());
 84	
 85	            if (checkIn == null || checkOut == null) {
 86	                error(ctx, 400, "INVALID_REQUEST", "Invalid date format");
 87	                return;
 88	            }
 89	
 90	            if (!ValidationUtil.isValidDateRange(checkIn, checkOut)) {
 91	                error(ctx, 400, "INVALID_REQUEST", "Check-out must be after check-in");
 92	                return;
 93	            }
 94	
 95	            Room room = RoomService.getRoom(roomNumber);
 96	            if (room == null) {
 97	                error(ctx, 404, "ROOM_NOT_FOUND", "Room not found");
 98	                return;
 99	            }
100	
101	            if (guests < 1) {
102	                error(ctx, 400, "INVALID_REQUEST", "At least one guest required");
103	                return;
104	            }
105	
106	            if (guests > room.capacity) {
107	                error(ctx, 422, "CAPACITY_EXCEEDED", "Too many guests for this room");
108	                return;
109	            }
110	
111	            if (!ReservationService.isRoomAvailable(roomNumber, checkIn, checkOut)) {
112	                error(ctx, 409, "ROOM_UNAVAILABLE", "Room is not available for these dates");
113	                return;
114	            }
115	
116	            Reservation reservation = ReservationService.create(roomNumber, guestName, guestEmail, guestCpf,
117	                                                                 checkIn, checkOut, guests, ratePlan);
118	            ctx.status(201);
119	            ctx.json(formatReservation(reservation));
120	        } catch (Exception e) {
121	            error(ctx, 500, "INTERNAL_ERROR", e.getMessage());
122	        }
123	    }
124	
125	    private static void getReservation(Context ctx) {
126	        try {
127	            int id = Integer.parseInt(ctx.pathParam("id"));
128	            Reservation res = ReservationService.getReservation(id);
129	
130	            if (res == null) {
131	                error(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
132	                return;
133	            }
134	
135	            ctx.json(formatReservation(res));
136	        } catch (Exception e) {
137	            error(ctx, 500, "INTERNAL_ERROR", e.getMessage());
138	        }
139	    }
140	
141	    private static void confirmReservation(Context ctx) {
142	        try {
143	            int id = Integer.parseInt(ctx.pathParam("id"));
144	            JsonNode body = ctx.bodyAsClass(JsonNode.class);
145	
146	            Reservation res = ReservationService.getReservation(id);
147	            if (res == null) {
148	                error(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
149	                return;
150	            }
151	
152	            res = ReservationService.confirm(id, res.total);
153	
154	            Room room = RoomService.getRoom(res.roomNumber);
155	            res.roomType = room.type;
156	
157	            String receipt = DocumentService.generateReceipt(res);
158	            MessageService.sendReservationConfirmation(id, res.guestName, res.guestEmail, receipt);
159	
160	            ctx.json(formatReservation(res));
161	        } catch (IllegalStateException e) {
162	            error(ctx, 409, "OPERATION_NOT_ALLOWED", e.getMessage());
163	        } catch (Exception e) {
164	            error(ctx, 500, "INTERNAL_ERROR", e.getMessage());
165	        }
166	    }
