168	    private static void checkIn(Context ctx) {
169	        try {
170	            int id = Integer.parseInt(ctx.pathParam("id"));
171	            Reservation res = ReservationService.getReservation(id);
172	
173	            if (res == null) {
174	                error(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
175	                return;
176	            }
177	
178	            res = ReservationService.checkIn(id);
179	            ctx.json(formatReservation(res));
180	        } catch (IllegalStateException e) {
181	            error(ctx, 409, "OPERATION_NOT_ALLOWED", e.getMessage());
