187	    private static void checkOut(Context ctx) {
188	        try {
189	            int id = Integer.parseInt(ctx.pathParam("id"));
190	            Reservation res = ReservationService.getReservation(id);
191	
192	            if (res == null) {
193	                error(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
194	                return;
195	            }
196	
197	            res = ReservationService.checkOut(id);
198	            Room room = RoomService.getRoom(res.roomNumber);
199	            res.roomType = room.type;
200	
201	            DocumentService.ReceiptResponse receipt = new DocumentService.ReceiptResponse(res);
202	            ctx.json(receipt);
203	        } catch (IllegalStateException e) {
204	            error(ctx, 409, "OPERATION_NOT_ALLOWED", e.getMessage());
205	        } catch (Exception e) {
206	            error(ctx, 500, "INTERNAL_ERROR", e.getMessage());
207	        }
208	    }
209	
210	    private static void cancelReservation(Context ctx) {
211	        try {
212	            int id = Integer.parseInt(ctx.pathParam("id"));
213	            Reservation res = ReservationService.getReservation(id);
214	
215	            if (res == null) {
216	                error(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
217	                return;
218	            }
219	
220	            res = ReservationService.cancel(id);
221	            ctx.json(formatReservation(res));
222	        } catch (IllegalStateException e) {
223	            error(ctx, 409, "OPERATION_NOT_ALLOWED", e.getMessage());
224	        } catch (Exception e) {
225	            error(ctx, 500, "INTERNAL_ERROR", e.getMessage());
226	        }
227	    }
228	
229	    private static void getDocument(Context ctx) {
230	        try {
231	            int id = Integer.parseInt(ctx.pathParam("id"));
232	            Reservation res = ReservationService.getReservation(id);
233	
234	            if (res == null) {
235	                error(ctx, 404, "RESERVATION_NOT_FOUND", "Reservation not found");
236	                return;
237	            }
238	
239	            if (res.amountPaid == null || res.amountPaid.compareTo(BigDecimal.ZERO) == 0) {
240	                error(ctx, 409, "OPERATION_NOT_ALLOWED", "No receipt available for unpaid reservations");
241	                return;
242	            }
243	
244	            Room room = RoomService.getRoom(res.roomNumber);
245	            res.roomType = room.type;
246	
247	            DocumentService.ReceiptResponse receipt = new DocumentService.ReceiptResponse(res);
248	            ctx.json(receipt);
249	        } catch (Exception e) {
250	            error(ctx, 500, "INTERNAL_ERROR", e.getMessage());
251	        }
252	    }
253	
254	    private static void getMessages(Context ctx) {
255	        try {
256	            ctx.json(MessageService.getAllMessages());
257	        } catch (Exception e) {
258	            error(ctx, 500, "INTERNAL_ERROR", e.getMessage());
259	        }
260	    }
261	
262	    private static void getOccupancyReport(Context ctx) {
263	        try {
264	            String dateStr = ctx.queryParam("date");
265	            if (dateStr == null) {
266	                error(ctx, 400, "INVALID_REQUEST", "Missing date parameter");
267	                return;
268	            }
269	
270	            LocalDate date = ValidationUtil.parseDate(dateStr);
271	            if (date == null) {
272	                error(ctx, 400, "INVALID_REQUEST", "Invalid date format");
273	                return;
274	            }
275	
276	            String csv = ReportService.getOccupancyReport(date);
277	            ctx.contentType("text/csv; charset=utf-8");
278	            ctx.result(csv);
279	        } catch (Exception e) {
280	            error(ctx, 500, "INTERNAL_ERROR", e.getMessage());
281	        }
282	    }
283	
284	    private static void getRevenueReport(Context ctx) {
285	        try {
286	            String monthStr = ctx.queryParam("month");
287	            if (monthStr == null) {
288	                error(ctx, 400, "INVALID_REQUEST", "Missing month parameter");
289	                return;
290	            }
291	
292	            YearMonth month = ValidationUtil.parseYearMonth(monthStr);
293	            if (month == null) {
294	                error(ctx, 400, "INVALID_REQUEST", "Invalid month format");
295	                return;
296	            }
297	
298	            String csv = ReportService.getRevenueReport(month);
299	            ctx.contentType("text/csv; charset=utf-8");
300	            ctx.result(csv);
301	        } catch (Exception e) {
302	            error(ctx, 500, "INTERNAL_ERROR", e.getMessage());
303	        }
304	    }
305	
306	    private static Object formatReservation(Reservation res) throws Exception {
307	        return new Object() {
308	            public int id = res.id;
309	            public int roomNumber = res.roomNumber;
310	            public String guestName = res.guestName;
311	            public String guestEmail = res.guestEmail;
312	            public String guestCpf = res.guestCpf;
313	            public String checkIn = res.checkIn.toString();
314	            public String checkOut = res.checkOut.toString();
315	            public int guests = res.guests;
316	            public String ratePlan = res.ratePlan;
317	            public int nights = res.nights;
318	            public BigDecimal subtotal = res.subtotal;
319	            public BigDecimal discount = res.discount;
320	            public BigDecimal total = res.total;
321	            public String status = res.status;
322	            public BigDecimal amountPaid = res.amountPaid;
323	            public BigDecimal refund = res.refund;
324	        };
325	    }
326	
327	    private static void error(Context ctx, int status, String code, String message) {
328	        ctx.status(status);
329	        final String finalCode = code;
330	        final String finalMessage = message;
331	        ctx.json(new Object() {
332	            public String error = finalCode;
333	            public String message = finalMessage;
334	        });
335	    }
336	
337	    private static boolean hasRequiredFields(JsonNode body, String... fields) {
338	        for (String field : fields) {
339	            if (!body.has(field) || body.get(field).isNull()) {
340	                return false;
341	            }
342	        }
343	        return true;
344	    }
345	}
346	package com.pousadamarealta.database;
347	
348	import com.zaxxer.hikari.HikariConfig;
349	import com.zaxxer.hikari.HikariDataSource;
350	import java.sql.Connection;
351	import java.sql.SQLException;
352	
353	public class Database {
354	    private static HikariDataSource dataSource;
355	
356	    public static void initialize() {
357	        String dbUrl = System.getenv("DB_URL");
358	        String dbUser = System.getenv("DB_USER");
359	        String dbPassword = System.getenv("DB_PASSWORD");
360	
361	        if (dbUrl == null || dbUser == null || dbPassword == null) {
362	            throw new IllegalStateException("Missing database environment variables");
363	        }
364	
365	        HikariConfig config = new HikariConfig();
366	        config.setJdbcUrl(dbUrl);
367	        config.setUsername(dbUser);
368	        config.setPassword(dbPassword);
369	        config.setMaximumPoolSize(10);
370	
371	        dataSource = new HikariDataSource(config);
372	
373	        createTables();
374	    }
375	
376	    public static Connection getConnection() throws SQLException {
377	        return dataSource.getConnection();
378	    }
379	
380	    private static void createTables() {
381	        try (Connection conn = getConnection()) {
382	            conn.createStatement().execute("""
383	                CREATE TABLE IF NOT EXISTS rooms (
384	                    number INTEGER PRIMARY KEY,
385	                    type VARCHAR(20) NOT NULL,
386	                    capacity INTEGER NOT NULL,
387	                    nightly_rate NUMERIC(10, 2) NOT NULL
388	                )
389	                """);
390	
391	            conn.createStatement().execute("""
392	                CREATE TABLE IF NOT EXISTS reservations (
393	                    id SERIAL PRIMARY KEY,
394	                    room_number INTEGER NOT NULL REFERENCES rooms(number),
395	                    guest_name VARCHAR(255) NOT NULL,
396	                    guest_email VARCHAR(255) NOT NULL,
397	                    guest_cpf VARCHAR(20) NOT NULL,
398	                    check_in DATE NOT NULL,
399	                    check_out DATE NOT NULL,
400	                    guests INTEGER NOT NULL,
401	                    rate_plan VARCHAR(20) NOT NULL,
402	                    nights INTEGER NOT NULL,
403	                    subtotal NUMERIC(10, 2) NOT NULL,
404	                    discount NUMERIC(10, 2) NOT NULL,
405	                    total NUMERIC(10, 2) NOT NULL,
406	                    status VARCHAR(20) NOT NULL,
407	                    amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
408	                    refund NUMERIC(10, 2),
409	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
410	                )
411	                """);
412	
413	            conn.createStatement().execute("""
414	                CREATE TABLE IF NOT EXISTS messages (
415	                    id SERIAL PRIMARY KEY,
416	                    channel VARCHAR(20) NOT NULL,
417	                    "to" VARCHAR(255) NOT NULL,
418	                    subject VARCHAR(255) NOT NULL,
419	                    body TEXT NOT NULL,
420	                    status VARCHAR(20) NOT NULL,
421	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
422	                )
423	                """);
424	
425	            insertInitialRooms(conn);
426	        } catch (SQLException e) {
427	            throw new RuntimeException("Failed to initialize database", e);
428	        }
429	    }
430	
431	    private static void insertInitialRooms(Connection conn) throws SQLException {
432	        var checkRooms = conn.createStatement().executeQuery("SELECT COUNT(*) as count FROM rooms");
433	        checkRooms.next();
434	        if (checkRooms.getInt("count") > 0) {
435	            return;
436	        }
437	
438	        conn.createStatement().execute("""
439	            INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
440	            (101, 'STANDARD', 2, 249.90),
441	            (102, 'STANDARD', 2, 249.90),
442	            (201, 'DELUXE', 3, 389.90),
443	            (202, 'DELUXE', 3, 389.90),
444	            (301, 'SUITE', 4, 579.90)
445	            """);
446	    }
447	}

