  9	
 10	public class DocumentService {
 11	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 12	    private static final DecimalFormatSymbols SYMBOLS = new DecimalFormatSymbols(Locale.US);
 13	    private static final DecimalFormat MONEY_FORMAT = new DecimalFormat("0.00", SYMBOLS);
 14	
 15	    public static String generateReceipt(Reservation reservation) {
 16	        StringBuilder receipt = new StringBuilder();
 17	        receipt.append("Comprovante de reserva nº ").append(reservation.id).append("\n");
 18	        receipt.append("Hóspede: ").append(reservation.guestName).append(" (CPF ").append(formatCpf(reservation.guestCpf)).append(")\n");
 19	        receipt.append("Quarto: ").append(reservation.roomNumber).append(" (").append(reservation.roomType).append(")\n");
 20	        receipt.append("Entrada: ").append(reservation.checkIn.format(DATE_FORMATTER)).append(" | ");
 21	        receipt.append("Saída: ").append(reservation.checkOut.format(DATE_FORMATTER)).append(" | ");
 22	        receipt.append(reservation.nights).append(" diária").append(reservation.nights > 1 ? "s" : "").append("\n");
 23	        receipt.append("Diárias: ").append(formatMoney(reservation.subtotal)).append("\n");
 24	
 25	        if (reservation.discount.compareTo(java.math.BigDecimal.ZERO) > 0) {
 26	            receipt.append("Desconto: ").append(formatMoney(reservation.discount)).append("\n");
 27	        }
 28	
 29	        receipt.append("Total: ").append(formatMoney(reservation.total));
 30	
 31	        return receipt.toString();
 32	    }
 33	
 34	    public static class ReceiptResponse {
 35	        public String title = "Comprovante de reserva";
 36	        public int reservationId;
 37	        public String guestName;
 38	        public String guestCpf;
 39	        public int roomNumber;
 40	        public String roomType;
 41	        public String checkIn;
 42	        public String checkOut;
 43	        public int nights;
 44	        public BigDecimal subtotal;
 45	        public BigDecimal discount;
 46	        public BigDecimal total;
 47	
 48	        public ReceiptResponse(Reservation reservation) {
 49	            this.reservationId = reservation.id;
 50	            this.guestName = reservation.guestName;
 51	            this.guestCpf = formatCpf(reservation.guestCpf);
 52	            this.roomNumber = reservation.roomNumber;
 53	            this.roomType = reservation.roomType;
 54	            this.checkIn = reservation.checkIn.format(DATE_FORMATTER);
 55	            this.checkOut = reservation.checkOut.format(DATE_FORMATTER);
 56	            this.nights = reservation.nights;
 57	            this.subtotal = reservation.subtotal;
 58	            this.discount = reservation.discount;
 59	            this.total = reservation.total;
 60	        }
 61	    }
 62	
 63	    private static String formatMoney(BigDecimal value) {
 64	        return "R$ " + MONEY_FORMAT.format(value).replace(".", ",");
 65	    }
 66	
 67	    private static String formatCpf(String cpf) {
 68	        if (cpf == null || cpf.length() != 11) {
 69	            return cpf;
 70	        }
 71	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
 72	               cpf.substring(6, 9) + "-" + cpf.substring(9);
 73	    }
 74	}
