 86	public class MessageService {
 87	    private static final String ARCHIVE_EMAIL = "arquivo@pousadamarealta.com.br";
 88	    private static final String TEST_EMAIL = "testes@pousadamarealta.com.br";
 89	    private static final boolean TEST_MODE = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 90	
 91	    public static void sendReservationConfirmation(int reservationId, String guestName, String guestEmail, String receipt) throws SQLException {
 92	        String subject = "Reserva confirmada - Pousada Maré Alta";
 93	        String body = "Olá, " + guestName + "!\n\n" +
 94	                      "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
 95	                      receipt + "\n\n" +
 96	                      "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
 97	                      "Até breve!";
 98	
 99	        sendMessage("EMAIL", guestEmail, subject, body);
