102	    public static void sendMessage(String channel, String to, String subject, String body) throws SQLException {
103	        if (!ValidationUtil.isValidEmail(to)) {
104	            insertMessage(channel, to, subject, body, "BLOCKED");
105	            return;
106	        }
107	
108	        String finalTo = to;
109	        String finalSubject = subject;
110	        String finalBody = body;
111	
112	        if (TEST_MODE) {
113	            finalBody = "Destinatário original: " + to + "\n" + body;
114	            finalSubject = "[TESTE] " + subject;
115	            finalTo = TEST_EMAIL;
116	        }
117	
118	        insertMessage(channel, finalTo, finalSubject, finalBody, "SENT");
119	
120	        if (!TEST_MODE && !finalTo.equals(to)) {
121	            String archiveSubject = "[Cópia] " + subject;
122	            insertMessage(channel, ARCHIVE_EMAIL, archiveSubject, body, "SENT");
123	        }
124	    }
