126	    public static List<Message> getAllMessages() throws SQLException {
127	        List<Message> messages = new ArrayList<>();
128	        try (Connection conn = Database.getConnection()) {
129	            var rs = conn.createStatement().executeQuery(
130	                "SELECT id, channel, \"to\", subject, body, status FROM messages ORDER BY id");
131	
132	            while (rs.next()) {
133	                messages.add(rowToMessage(rs));
134	            }
135	        }
136	        return messages;
137	    }
