139	    private static void insertMessage(String channel, String to, String subject, String body, String status) throws SQLException {
140	        try (Connection conn = Database.getConnection()) {
141	            var stmt = conn.prepareStatement(
142	                "INSERT INTO messages (channel, \"to\", subject, body, status) VALUES (?, ?, ?, ?, ?)");
143	            stmt.setString(1, channel);
144	            stmt.setString(2, to);
145	            stmt.setString(3, subject);
146	            stmt.setString(4, body);
147	            stmt.setString(5, status);
148	            stmt.executeUpdate();
149	        }
150	    }
151	
152	    private static Message rowToMessage(ResultSet rs) throws SQLException {
153	        return new Message(
154	            rs.getInt("id"),
155	            rs.getString("channel"),
156	            rs.getString("to"),
157	            rs.getString("subject"),
158	            rs.getString("body"),
159	            rs.getString("status")
160	        );
161	    }
