174	public class ReportService {
175	    public static String getOccupancyReport(LocalDate date) throws SQLException {
176	        StringBuilder csv = new StringBuilder();
177	        csv.append("room,type,reservation,check_in,check_out\n");
178	
179	        try (Connection conn = Database.getConnection()) {
180	            var stmt = conn.prepareStatement(
181	                "SELECT r.number, r.type, res.id, res.check_in, res.check_out " +
182	                "FROM rooms r " +
183	                "LEFT JOIN reservations res ON r.number = res.room_number " +
184	                "AND res.status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT') " +
185	                "AND res.check_in <= ? " +
186	                "AND res.check_out > ? " +
187	                "ORDER BY r.number");
188	            stmt.setObject(1, date);
189	            stmt.setObject(2, date);
190	
191	            var rs = stmt.executeQuery();
192	
193	            int occupied = 0;
194	            while (rs.next()) {
195	                int roomNumber = rs.getInt("number");
196	                String type = rs.getString("type");
197	                Object reservationId = rs.getObject("id");
198	
199	                if (reservationId != null) {
200	                    String checkIn = rs.getObject("check_in").toString();
201	                    String checkOut = rs.getObject("check_out").toString();
202	                    csv.append(roomNumber).append(",").append(type).append(",")
203	                       .append(reservationId).append(",").append(checkIn).append(",")
204	                       .append(checkOut).append("\n");
205	                    occupied++;
206	                }
207	            }
208	
209	            csv.append("total,").append(occupied).append("/5\n");
210	        }
211	
212	        return csv.toString();
213	    }
