215	    public static String getRevenueReport(YearMonth month) throws SQLException {
216	        StringBuilder csv = new StringBuilder();
217	        csv.append("reservation,room,check_in,check_out,status,amount\n");
218	
219	        java.math.BigDecimal totalRevenue = java.math.BigDecimal.ZERO;
220	
221	        try (Connection conn = Database.getConnection()) {
222	            LocalDate monthStart = month.atDay(1);
223	            LocalDate monthEnd = month.atEndOfMonth();
224	
225	            var stmt = conn.prepareStatement(
226	                "SELECT id, room_number, check_in, check_out, status, amount_paid, refund " +
227	                "FROM reservations " +
228	                "WHERE check_in >= ? " +
229	                "AND check_in <= ? " +
230	                "AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELLED') " +
231	                "AND (amount_paid > 0 OR refund > 0) " +
232	                "ORDER BY check_in, id");
233	            stmt.setObject(1, monthStart);
234	            stmt.setObject(2, monthEnd);
235	
236	            var rs = stmt.executeQuery();
237	
238	            while (rs.next()) {
239	                int id = rs.getInt("id");
240	                int room = rs.getInt("room_number");
241	                String checkIn = rs.getObject("check_in").toString();
242	                String checkOut = rs.getObject("check_out").toString();
243	                String status = rs.getString("status");
244	                java.math.BigDecimal amountPaid = rs.getBigDecimal("amount_paid");
245	                java.math.BigDecimal refund = rs.getBigDecimal("refund");
246	
247	                java.math.BigDecimal net = amountPaid;
248	                if (refund != null) {
249	                    net = net.subtract(refund);
250	                }
251	
252	                if (net.compareTo(java.math.BigDecimal.ZERO) != 0) {
253	                    csv.append(id).append(",").append(room).append(",")
254	                       .append(checkIn).append(",").append(checkOut).append(",")
255	                       .append(status).append(",").append(net.toPlainString()).append("\n");
256	
257	                    totalRevenue = totalRevenue.add(net);
258	                }
259	            }
260	
261	            csv.append("total,").append(totalRevenue.toPlainString()).append("\n");
262	        }
263	
264	        return csv.toString();
265	    }
