278	public class ReservationService {
279	    public static Reservation create(int roomNumber, String guestName, String guestEmail, String guestCpf,
280	                                      LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan) throws SQLException {
281	        int nights = PricingUtil.calculateNights(checkIn, checkOut);
282	
283	        try (Connection conn = Database.getConnection()) {
284	            var roomStmt = conn.prepareStatement(
285	                "SELECT nightly_rate FROM rooms WHERE number = ?");
286	            roomStmt.setInt(1, roomNumber);
287	            var roomRs = roomStmt.executeQuery();
288	
289	            if (!roomRs.next()) {
290	                throw new IllegalArgumentException("ROOM_NOT_FOUND");
291	            }
292	
293	            BigDecimal baseRate = new BigDecimal(roomRs.getString("nightly_rate"));
294	            BigDecimal subtotal = PricingUtil.calculateSubtotal(baseRate, checkIn, checkOut);
295	            BigDecimal discount = PricingUtil.calculateDiscount(subtotal, ratePlan);
296	            BigDecimal total = PricingUtil.calculateTotal(subtotal, discount);
297	
298	            var insertStmt = conn.prepareStatement(
299	                "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, " +
300	                "check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) " +
301	                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'PENDING', 0) RETURNING id",
302	                java.sql.Statement.RETURN_GENERATED_KEYS);
303	
304	            insertStmt.setInt(1, roomNumber);
305	            insertStmt.setString(2, guestName);
306	            insertStmt.setString(3, guestEmail);
307	            insertStmt.setString(4, guestCpf);
308	            insertStmt.setObject(5, checkIn);
309	            insertStmt.setObject(6, checkOut);
310	            insertStmt.setInt(7, guests);
311	            insertStmt.setString(8, ratePlan);
312	            insertStmt.setInt(9, nights);
313	            insertStmt.setBigDecimal(10, subtotal);
314	            insertStmt.setBigDecimal(11, discount);
315	            insertStmt.setBigDecimal(12, total);
316	
317	            insertStmt.executeUpdate();
318	            var rs = insertStmt.getGeneratedKeys();
319	            rs.next();
320	            int id = rs.getInt(1);
321	
322	            return getReservation(id);
323	        }
324	    }
325	
326	    public static Reservation getReservation(int id) throws SQLException {
327	        try (Connection conn = Database.getConnection()) {
328	            var stmt = conn.prepareStatement(
329	                "SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, " +
330	                "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund " +
331	                "FROM reservations WHERE id = ?");
332	            stmt.setInt(1, id);
333	            var rs = stmt.executeQuery();
334	
335	            if (!rs.next()) {
336	                return null;
