    86	package com.pousadamarealta.util;
    87	
    88	import java.math.BigDecimal;
    89	import java.math.RoundingMode;
    90	import java.time.LocalDate;
    91	
    92	public class PricingUtil {
    93	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    94	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    95	
    96	    public static BigDecimal round(BigDecimal value) {
    97	        return value.setScale(2, RoundingMode.HALF_EVEN);
    98	    }
    99	
   100	    public static boolean isHighSeason(LocalDate date) {
   101	        int month = date.getMonthValue();
   102	        int day = date.getDayOfMonth();
   103	
   104	        if (month == 7) return true;
   105	
   106	        if (month == 1 || month == 2) return true;
   107	
   108	        if (month == 12 && day >= 15) return true;
   109	
   110	        return false;
   111	    }
   112	
   113	    public static BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate date) {
   114	        BigDecimal price = baseRate;
   115	        if (isHighSeason(date)) {
   116	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
   117	        }
   118	        return round(price);
   119	    }
   120	
   121	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
   122	        BigDecimal subtotal = BigDecimal.ZERO;
   123	        LocalDate current = checkIn;
   124	        while (current.isBefore(checkOut)) {
   125	            subtotal = subtotal.add(calculateNightPrice(baseRate, current));
   126	            current = current.plusDays(1);
   127	        }
   128	        return round(subtotal);
   129	    }
   130	
   131	    public static BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
   132	        if ("NON_REFUNDABLE".equals(ratePlan)) {
   133	            return round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
   134	        }
   135	        return BigDecimal.ZERO;
   136	    }
   137	
   138	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
   139	        return round(subtotal.subtract(discount));
   140	    }
   141	
   142	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
   143	        return (int) (checkOut.toEpochDay() - checkIn.toEpochDay());
   144	    }
   145	}
