   154	        if (email == null || email.isBlank()) {
   155	            return false;
   156	        }
   157	
   158	        int atIndex = email.indexOf('@');
   159	
   160	        if (atIndex != email.lastIndexOf('@')) {
   161	            return false;
   162	        }
   163	
   164	        if (atIndex <= 0 || atIndex == email.length() - 1) {
   165	            return false;
   166	        }
   167	
   168	        String domain = email.substring(atIndex + 1);
   169	
   170	        if (!domain.contains(".")) {
   171	            return false;
   172	        }
   173	
   174	        return true;
   175	    }
