  1	package com.pousadamarealta.util;
  2	
  3	import org.junit.Test;
  4	import static org.junit.Assert.*;
  5	import java.math.BigDecimal;
  6	import java.time.LocalDate;
  7	
  8	public class PricingUtilTest {
  9	    @Test
 10	    public void testHighSeasonJuly() {
 11	        assertTrue(PricingUtil.isHighSeason(LocalDate.of(2027, 7, 10)));
 12	        assertTrue(PricingUtil.isHighSeason(LocalDate.of(2027, 7, 15)));
 13	    }
 14	
 15	    @Test
 16	    public void testHighSeasonDecToFeb() {
 17	        assertTrue(PricingUtil.isHighSeason(LocalDate.of(2026, 12, 15)));
 18	        assertTrue(PricingUtil.isHighSeason(LocalDate.of(2026, 12, 25)));
 19	        assertTrue(PricingUtil.isHighSeason(LocalDate.of(2027, 1, 15)));
 20	        assertTrue(PricingUtil.isHighSeason(LocalDate.of(2027, 2, 28)));
 21	        assertFalse(PricingUtil.isHighSeason(LocalDate.of(2026, 12, 14)));
 22	    }
 23	
 24	    @Test
 25	    public void testLowSeason() {
 26	        assertFalse(PricingUtil.isHighSeason(LocalDate.of(2027, 3, 15)));
 27	        assertFalse(PricingUtil.isHighSeason(LocalDate.of(2027, 6, 15)));
 28	        assertFalse(PricingUtil.isHighSeason(LocalDate.of(2027, 11, 15)));
 29	    }
 30	
 31	    @Test
 32	    public void testCalculateNightPrice() {
 33	        BigDecimal baseRate = new BigDecimal("249.90");
 34	
 35	        LocalDate lowSeason = LocalDate.of(2027, 6, 10);
 36	        BigDecimal lowSeasonPrice = PricingUtil.calculateNightPrice(baseRate, lowSeason);
 37	        assertEquals(new BigDecimal("249.90"), lowSeasonPrice);
 38	
 39	        LocalDate highSeason = LocalDate.of(2027, 7, 10);
 40	        BigDecimal highSeasonPrice = PricingUtil.calculateNightPrice(baseRate, highSeason);
 41	        assertEquals(new BigDecimal("299.88"), highSeasonPrice);
 42	    }
 43	
 44	    @Test
 45	    public void testCalculateSubtotal() {
 46	        BigDecimal baseRate = new BigDecimal("249.90");
 47	        LocalDate checkIn = LocalDate.of(2027, 7, 10);
 48	        LocalDate checkOut = LocalDate.of(2027, 7, 12);
 49	
 50	        BigDecimal subtotal = PricingUtil.calculateSubtotal(baseRate, checkIn, checkOut);
 51	        assertEquals(new BigDecimal("599.76"), subtotal);
 52	    }
 53	
 54	    @Test
 55	    public void testCalculateDiscount() {
 56	        BigDecimal subtotal = new BigDecimal("599.76");
 57	
 58	        BigDecimal standardDiscount = PricingUtil.calculateDiscount(subtotal, "STANDARD");
 59	        assertEquals(BigDecimal.ZERO, standardDiscount);
 60	
 61	        BigDecimal nonRefundableDiscount = PricingUtil.calculateDiscount(subtotal, "NON_REFUNDABLE");
 62	        assertEquals(new BigDecimal("89.96"), nonRefundableDiscount);
 63	    }
 64	
 65	    @Test
 66	    public void testRounding() {
 67	        BigDecimal value = new BigDecimal("249.895");
 68	        BigDecimal rounded = PricingUtil.round(value);
 69	        assertEquals(new BigDecimal("249.90"), rounded);
 70	
 71	        BigDecimal value2 = new BigDecimal("249.894");
 72	        BigDecimal rounded2 = PricingUtil.round(value2);
 73	        assertEquals(new BigDecimal("249.89"), rounded2);
 74	    }
 75	
 76	    @Test
 77	    public void testCalculateNights() {
 78	        LocalDate checkIn = LocalDate.of(2027, 7, 10);
 79	        LocalDate checkOut = LocalDate.of(2027, 7, 12);
 80	        assertEquals(2, PricingUtil.calculateNights(checkIn, checkOut));
 81	
 82	        LocalDate checkOut2 = LocalDate.of(2027, 7, 11);
 83	        assertEquals(1, PricingUtil.calculateNights(checkIn, checkOut2));
 84	    }
 85	}
 86	package com.pousadamarealta.util;
 87	
 88	import org.junit.Test;
 89	import static org.junit.Assert.*;
 90	
 91	public class ValidationUtilTest {
 92	    @Test
 93	    public void testValidEmail() {
 94	        assertTrue(ValidationUtil.isValidEmail("ana@gmail.com"));
 95	        assertTrue(ValidationUtil.isValidEmail("user@example.co.uk"));
 96	        assertTrue(ValidationUtil.isValidEmail("test@sub.domain.com"));
 97	    }
 98	
 99	    @Test
100	    public void testInvalidEmail() {
101	        assertFalse(ValidationUtil.isValidEmail("ana@gmail"));
102	        assertFalse(ValidationUtil.isValidEmail("ana.gmail.com"));
103	        assertFalse(ValidationUtil.isValidEmail("@gmail.com"));
104	        assertFalse(ValidationUtil.isValidEmail("ana@"));
105	        assertFalse(ValidationUtil.isValidEmail("ana@@gmail.com"));
106	        assertFalse(ValidationUtil.isValidEmail(""));
107	        assertFalse(ValidationUtil.isValidEmail(null));
108	    }
109	
110	    @Test
111	    public void testValidDateRange() {
112	        var checkIn = java.time.LocalDate.of(2027, 7, 10);
113	        var checkOut = java.time.LocalDate.of(2027, 7, 12);
114	        assertTrue(ValidationUtil.isValidDateRange(checkIn, checkOut));
115	    }
116	
117	    @Test
118	    public void testInvalidDateRange() {
119	        var checkIn = java.time.LocalDate.of(2027, 7, 12);
120	        var checkOut = java.time.LocalDate.of(2027, 7, 10);
121	        assertFalse(ValidationUtil.isValidDateRange(checkIn, checkOut));
122	
123	        assertFalse(ValidationUtil.isValidDateRange(null, java.time.LocalDate.of(2027, 7, 10)));
124	    }
125	}

